/**
 * How Embracing antlers in a circle (`maru-ni-daki-tsuno`) is constructed, in a line in each language: the text a crest's card shows beside its steps.
 * It is here, not on the crest's record, so that the manifest stays small; `crestConstruction()` loads it.
 *
 * @example
 * ```ts no-run
 * import { description } from "@johnmorrisdotca/kamon-crests/steps/maru-ni-daki-tsuno";
 *
 * console.log(description.en.length > 30, description.ja.endsWith("。")); // true true
 * ```
 */
const description: { en: string; ja: string } = {"en":"Draw the narrow ring and the antler outlines from compass arcs. Dot each antler and rule the short lines above its base. Mirror the pair on the upright axis within the circle.","ja":"細輪と角の輪郭を円弧で描きます。角に点を打ち、根元の上に短い線を引きます。輪の中で中心線を軸に左右対称に置きます。"};

export default construction;
export { construction, description };
